import{_ as i,a0 as o,w as l,s as u,I as a,x as t,a1 as r,A as s,ao as p}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const L=JSON.parse('{"title":"Linux 下的密碼管理器：Keeweb | LCTT x X-CMD","titleTemplate":false,"description":"Linux 下的密碼管理器：Keeweb | LCTT (201608) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux 下的密碼管理器：Keeweb | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux 下的密碼管理器：Keeweb | LCTT (201608) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201608/20160722 Keeweb A Linux Password Manager","title":"Linux 下的密碼管理器：Keeweb","tag":"201608","desc":""},"relativePath":"201608/20160722 Keeweb A Linux Password Manager.md","filePath":"[post].md"}'),w={name:"201608/20160722 Keeweb A Linux Password Manager.md"};function d(b,e,m,x,g,h){const n=o("Link");return l(),u("div",null,[e[16]||(e[16]=a("h1",{id:"linux-下的密碼管理器-keeweb",tabindex:"-1"},[t("Linux 下的密碼管理器：Keeweb "),a("a",{class:"header-anchor",href:"#linux-下的密碼管理器-keeweb","aria-label":"Permalink to “Linux 下的密碼管理器：Keeweb”"},"​")],-1)),e[17]||(e[17]=a("p",null,[a("img",{src:"http://www.linuxandubuntu.com/uploads/2/1/1/5/21152474/keeweb_1.png?608",alt:""})],-1)),e[18]||(e[18]=a("p",null,"如今，我們依賴於越來越多的線上服務。我們每註冊一個線上服務，就要設置一個密碼；如此，我們就不得不記住數以百計的密碼。這樣對於每個人來説，都很容易忘記密碼。我將在本文中介紹 Keeweb，它是一款 Linux 密碼管理器，可以為你離線或在線地安全存儲所有的密碼。",-1)),a("p",null,[e[2]||(e[2]=t("當談及 Linux 密碼管理器時，我們會發現有很多這樣的軟件。我們已經在 LinuxAndUbuntu 上討論過像 ",-1)),r(n,{href:"http://www.linuxandubuntu.com/home/keepass-password-management-tool-creates-strong-passwords-and-keeps-them-secure"},{default:s(()=>[...e[0]||(e[0]=[t("Keepass",-1)])]),_:1}),e[3]||(e[3]=t(" 和 ",-1)),r(n,{href:"http://www.linuxandubuntu.com/home/encryptr-zero-knowledge-system-based-password-manager-for-linux"},{default:s(()=>[...e[1]||(e[1]=[t("Encryptr，一個基於零知識系統的密碼管理器",-1)])]),_:1}),e[4]||(e[4]=t(" 這樣的密碼管理器。Keeweb 則是另外一款我們將在本文講解的 Linux 密碼管理器。",-1))]),e[19]||(e[19]=p('<h3 id="keeweb-可以離線或在線存儲密碼" tabindex="-1">Keeweb 可以離線或在線存儲密碼 <a class="header-anchor" href="#keeweb-可以離線或在線存儲密碼" aria-label="Permalink to “Keeweb 可以離線或在線存儲密碼”">​</a></h3><p>Keeweb 是一款跨平台的密碼管理器。它可以離線存儲你所有的密碼，並且能夠同步到你自己的雲存儲服務上，例如 OneDrive、Google Drive、Dropbox 等。Keeweb 並沒有它提供它自己的在線資料庫來的同步你的密碼。</p><p>要使用 Keeweb 連接你的線上存儲服務，只需要點擊界面中的“more”，然後再點擊你想要使用的服務即可。</p><p><img src="http://www.linuxandubuntu.com/uploads/2/1/1/5/21152474/keeweb.png?685" alt=""></p><p>現在，Keeweb 會提示你登錄到你的雲盤。登錄成功後，給 Keeweb 授權使用你的賬户。</p><p><img src="http://www.linuxandubuntu.com/uploads/2/1/1/5/21152474/authenticate-dropbox-with-keeweb_orig.jpg?649" alt=""></p><h3 id="使用-keeweb-存儲密碼" tabindex="-1">使用 Keeweb 存儲密碼 <a class="header-anchor" href="#使用-keeweb-存儲密碼" aria-label="Permalink to “使用 Keeweb 存儲密碼”">​</a></h3><p>使用 Keeweb 存儲你的密碼是非常容易的。你可以使用一個複雜的密碼加密你的密碼文件。Keeweb 也允許你使用一個秘鑰文件來鎖定密碼文件，但是我並不推薦這種方式。如果某個傢伙拿到了你的秘鑰文件，他只需要簡單點擊一下就可以解鎖你的密碼文件。</p><h4 id="創建密碼" tabindex="-1">創建密碼 <a class="header-anchor" href="#創建密碼" aria-label="Permalink to “創建密碼”">​</a></h4><p>想要創建一個新的密碼，你只需要簡單地點擊 <code>+</code> 號，然後你就會看到所有需要填充的輸入框。根據你的需要創建更多的密碼記錄。</p><h4 id="搜索密碼" tabindex="-1">搜索密碼 <a class="header-anchor" href="#搜索密碼" aria-label="Permalink to “搜索密碼”">​</a></h4><p><img src="http://www.linuxandubuntu.com/uploads/2/1/1/5/21152474/search-passwords_orig.png" alt=""></p><p>Keeweb 擁有一個圖標庫，這樣你就可以輕鬆地找到各種特定的密碼記錄。你可以改變圖標的顏色、下載更多的圖標，甚至可以直接從你的電腦中導入圖標。這對於密碼搜索來説，異常好使。</p><p>相似的服務的密碼可以分組，這樣你就可以在一個文件夾裏找到它們。你也可以給密碼打上標籤並把它們存放在不同分類中。</p><p><img src="http://www.linuxandubuntu.com/uploads/2/1/1/5/21152474/tags-passwords-in-keeweb.png?283" alt=""></p><h3 id="主題" tabindex="-1">主題 <a class="header-anchor" href="#主題" aria-label="Permalink to “主題”">​</a></h3><p><img src="http://www.linuxandubuntu.com/uploads/2/1/1/5/21152474/themes.png?304" alt=""></p><p>如果你喜歡類似於白色或者高對比度的亮色主題，你可以在“設置 &gt; 通用 &gt; 主題”中修改。（Keeweb）有四款可供選擇的主題，其中兩款為暗色，另外兩款為亮色。</p><h3 id="不喜歡-linux-密碼管理器-沒問題" tabindex="-1">不喜歡 Linux 密碼管理器？沒問題！ <a class="header-anchor" href="#不喜歡-linux-密碼管理器-沒問題" aria-label="Permalink to “不喜歡 Linux 密碼管理器？沒問題！”">​</a></h3><p>我已經發表過文章介紹了另外兩款 Linux 密碼管理器，它們分別是 Keepass 和 Encryptr，在 Reddit 和其它社交媒體上有些關於它們的爭論。有些人反對使用任何密碼管理器，也有人持相反意見。在本文中，我想要澄清的是，存放密碼文件是我們自己的責任。我認為像 keepass 和 Keeweb 這樣的密碼管理器是非常好用的，因為它們並沒有自己的雲來存放你的密碼。這些密碼管理器會創建一個文件，然後你可以將它存放在你的硬盤上，或者使用像 VeraCrypt 這樣的應用給它加密。我個人不使用也不推薦使用那些將密碼存儲在它們自己資料庫的服務。</p><hr>',21)),a("p",null,[e[6]||(e[6]=t("via: ",-1)),r(n,{href:"http://www.linuxandubuntu.com/home/keeweb-a-linux-password-manager"},{default:s(()=>[...e[5]||(e[5]=[t("http://www.linuxandubuntu.com/home/keeweb-a-linux-password-manager",-1)])]),_:1})]),a("p",null,[e[9]||(e[9]=t("譯者：",-1)),r(n,{href:"https://github.com/chrisleegit"},{default:s(()=>[...e[7]||(e[7]=[t("ChrisLeeGit",-1)])]),_:1}),e[10]||(e[10]=t(" 校對：",-1)),r(n,{href:"https://github.com/wxy"},{default:s(()=>[...e[8]||(e[8]=[t("wxy",-1)])]),_:1})]),a("p",null,[e[13]||(e[13]=t("本文由 ",-1)),r(n,{href:"https://github.com/LCTT/TranslateProject"},{default:s(()=>[...e[11]||(e[11]=[t("LCTT",-1)])]),_:1}),e[14]||(e[14]=t(" 原創編譯，",-1)),r(n,{href:"https://linux.cn/"},{default:s(()=>[...e[12]||(e[12]=[t("Linux中國",-1)])]),_:1}),e[15]||(e[15]=t(" 榮譽推出",-1))])])}const k=i(w,[["render",d]]);export{L as __pageData,k as default};
